package com.trampolim.api.career;
import java.util.*;import com.trampolim.api.radar.RadarBridge;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;
@Service public class CareerDeliveryWorker {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;private final java.util.concurrent.atomic.AtomicBoolean running=new java.util.concurrent.atomic.AtomicBoolean();private final java.util.concurrent.ExecutorService executor=java.util.concurrent.Executors.newSingleThreadExecutor(task->{var t=new Thread(task,"career-delivery");t.setDaemon(true);return t;});
 @Value("${career.delivery-enabled:true}")private boolean enabled;
 public CareerDeliveryWorker(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge){this.jdbc=jdbc;this.bridge=bridge;}
 @Scheduled(fixedDelayString="${career.delivery-delay-ms:30000}")public void scheduled(){if(!enabled||!running.compareAndSet(false,true))return;try{executor.execute(()->{try{deliver();}finally{running.set(false);}});}catch(java.util.concurrent.RejectedExecutionException closed){running.set(false);}}
 @jakarta.annotation.PreDestroy public void close(){executor.shutdownNow();}
 public int deliver(){var jobs=jdbc.queryForList("UPDATE career_delivery_jobs SET next_at=CURRENT_TIMESTAMP+INTERVAL '2 minutes' WHERE id IN (SELECT id FROM career_delivery_jobs WHERE status='PENDING' AND next_at<=CURRENT_TIMESTAMP ORDER BY created_at LIMIT 20 FOR UPDATE SKIP LOCKED) RETURNING *");int sent=0;for(var job:jobs){if(Thread.currentThread().isInterrupted())return sent;if(job.get("event_kind").equals("SUBMIT")&&job.get("owner_user_id")==null){jdbc.update("UPDATE career_delivery_jobs SET status='REJECTED',payload='{}' WHERE id=?",job.get("id"));continue;}try{bridge.post(job.get("event_kind").equals("SUBMIT")?"/integrations/career/challenges/submit":"/integrations/career/challenges/withdraw",bridge.convert(bridge.read(job.get("payload")),Map.class));jdbc.update("UPDATE career_delivery_jobs SET status='DELIVERED',payload='{}' WHERE id=? AND status='PENDING'",job.get("id"));sent++;}catch(org.springframework.web.server.ResponseStatusException error){boolean rejected=error.getStatusCode().is4xxClientError()&&error.getStatusCode().value()!=429;jdbc.update("UPDATE career_delivery_jobs SET status=?,payload=CASE WHEN ? THEN '{}'::jsonb ELSE payload END,attempts=LEAST(attempts+1,100),next_at=CURRENT_TIMESTAMP+make_interval(secs=>LEAST(3600,30*(attempts+1))) WHERE id=? AND status='PENDING'",rejected?"REJECTED":"PENDING",rejected,job.get("id"));}}return sent;}
}
